export const visualizationStyles = ":root {\n  color-scheme: light dark;\n  --background: light-dark(#fff, #202020);\n  --foreground: light-dark(#262626, #eee);\n  --card: var(--background);\n  --card-foreground: var(--foreground);\n  --popover: var(--background);\n  --popover-foreground: var(--foreground);\n  --muted: light-dark(#f4f4f4, #303030);\n  --muted-foreground: light-dark(#666, #aaa);\n  --primary: light-dark(#262626, #eee);\n  --primary-foreground: var(--background);\n  --secondary: var(--muted);\n  --secondary-foreground: var(--foreground);\n  --accent: var(--muted);\n  --accent-foreground: var(--foreground);\n  --border: light-dark(#ddd, #444);\n  --input: var(--border);\n  --ring: var(--foreground);\n  --blue: light-dark(#2563eb, #60a5fa);\n  --orange: light-dark(#c2410c, #fb923c);\n  --green: light-dark(#15803d, #4ade80);\n  --red: light-dark(#b91c1c, #f87171);\n  --purple: light-dark(#7e22ce, #c084fc);\n  --yellow: light-dark(#a16207, #facc15);\n  --destructive: var(--red);\n  --viz-series-1: var(--blue);\n  --viz-series-2: var(--orange);\n  --viz-series-3: var(--green);\n  --viz-series-4: var(--purple);\n  --viz-series-5: var(--red);\n  --viz-series-6: var(--yellow);\n  --font-size-base: 14px;\n}\n* {\n  box-sizing: border-box;\n}\nbody {\n  margin: 0;\n  padding: 12px;\n  font:\n    400 var(--font-size-base)/1.5 system-ui,\n    sans-serif;\n  color: var(--foreground);\n  background: var(--background);\n}\n[hidden] {\n  display: none !important;\n}\nbutton,\nselect,\ninput {\n  font: inherit;\n  color: inherit;\n}\nbutton,\nselect {\n  background: var(--background);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 6px 12px;\n  cursor: pointer;\n}\nbutton:disabled {\n  opacity: 0.4;\n  cursor: default;\n}\nsvg {\n  vertical-align: middle;\n}\n.text-small {\n  font-size: 12px;\n}\n.text-muted {\n  color: var(--muted-foreground);\n}\n.tabular-nums {\n  font-variant-numeric: tabular-nums;\n}\n.card {\n  padding: 16px;\n  border-radius: 12px;\n  background: var(--card);\n  color: var(--card-foreground);\n  border: 1px solid var(--border);\n}\n.btn-primary {\n  color: var(--primary-foreground);\n  background: var(--primary);\n}\n.viz-dotted-background {\n  background-image: radial-gradient(var(--border) 1px, transparent 1px);\n  background-size: 20px 20px;\n}\n.gravity-viz-navigation {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  padding: 16px 0;\n}\n.gravity-viz-navigation select {\n  max-width: calc(100% - 100px);\n}\n.gravity-viz-controls {\n  margin-top: 12px;\n  padding: 8px;\n  background: var(--background);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n}\n.gravity-viz-controls summary {\n  cursor: pointer;\n}\n.gravity-viz-controls label {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 12px;\n  padding: 8px;\n}\n";
